PRAGMA foreign_keys = ON;

-- Identity = keychain UUID generated by the iOS app on first launch (see HANDOFF.md §3).
-- No passwords. Existing databases were converted by migrate_001_users_device_uuid.py.
CREATE TABLE IF NOT EXISTS users (
  id          INTEGER PRIMARY KEY,
  device_uuid TEXT NOT NULL UNIQUE,                 -- canonical lowercase UUID from the iOS keychain
  name        TEXT NOT NULL,                        -- first name, friendly label only
  is_admin    INTEGER NOT NULL DEFAULT 0,           -- reserved; admin page is LAN-open in v1
  created_at  TEXT NOT NULL DEFAULT (datetime('now'))
);

-- sauces, toppings.style/image*, pizzas.sauce_id and favourites.sauce_id added by
-- migrate_004_sauces_photos_halves.py; toppings/pizzas sort_order + deleted by
-- migrate_005_order_and_delete.py
CREATE TABLE IF NOT EXISTS sauces (
  id         INTEGER PRIMARY KEY,
  name       TEXT NOT NULL UNIQUE,
  colour     TEXT NOT NULL DEFAULT '',        -- '#rrggbb' drawn by the app; '' = no sauce layer
  active     INTEGER NOT NULL DEFAULT 1,
  sort_order INTEGER NOT NULL DEFAULT 50
);

CREATE TABLE IF NOT EXISTS toppings (
  id         INTEGER PRIMARY KEY,
  name       TEXT NOT NULL UNIQUE,
  active     INTEGER NOT NULL DEFAULT 1,
  style      TEXT NOT NULL DEFAULT 'generic',  -- how the app draws it on the pizza (main.TOPPING_STYLES)
  image      BLOB,                             -- owner-uploaded photo (PNG/JPEG/WebP, ~256 px)
  image_type TEXT,                             -- its MIME type
  image_hash TEXT,                             -- sha1 of image; versions the image URL
  sort_order INTEGER NOT NULL DEFAULT 0,       -- owner's list order (migration 005)
  deleted    INTEGER NOT NULL DEFAULT 0        -- 1 = deleted in /admin; kept for order history
);

CREATE TABLE IF NOT EXISTS pizzas (
  id          INTEGER PRIMARY KEY,
  name        TEXT NOT NULL,
  description TEXT NOT NULL DEFAULT '',
  active      INTEGER NOT NULL DEFAULT 1,
  sauce_id    INTEGER REFERENCES sauces(id),  -- default sauce
  sort_order  INTEGER NOT NULL DEFAULT 0,     -- owner's menu order (migration 005)
  deleted     INTEGER NOT NULL DEFAULT 0      -- 1 = deleted in /admin; kept for order history
);

-- base toppings that come on a menu pizza; amounts per half added by migrate_006_menu_halves.py
CREATE TABLE IF NOT EXISTS pizza_toppings (
  pizza_id     INTEGER NOT NULL REFERENCES pizzas(id) ON DELETE CASCADE,
  topping_id   INTEGER NOT NULL REFERENCES toppings(id) ON DELETE CASCADE,
  left_amount  INTEGER NOT NULL DEFAULT 1 CHECK (left_amount BETWEEN 0 AND 2),   -- 0 none, 1 normal, 2 double
  right_amount INTEGER NOT NULL DEFAULT 1 CHECK (right_amount BETWEEN 0 AND 2),  -- never both 0 (checked in main.py)
  PRIMARY KEY (pizza_id, topping_id)
);

-- a saved pizza + customisation (columns added by migrate_002_favourites_customisation.py;
-- rebuilt by migrate_007_byo_favourites_suggestions.py so pizza_id may be NULL)
CREATE TABLE IF NOT EXISTS favourites (
  id            INTEGER PRIMARY KEY,
  user_id       INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  pizza_id      INTEGER REFERENCES pizzas(id) ON DELETE CASCADE,  -- NULL = build your own
  label         TEXT NOT NULL DEFAULT '',
  added_json    TEXT NOT NULL DEFAULT '[]',  -- menu pizza: extra topping ids
  removed_json  TEXT NOT NULL DEFAULT '[]',  -- menu pizza: base topping ids removed
  sauce_id      INTEGER REFERENCES sauces(id),  -- menu pizza: NULL = its default sauce; build your own: required
  toppings_json TEXT NOT NULL DEFAULT '[]',  -- build your own, or a menu pizza whose halves changed (migration 006)
  UNIQUE (user_id, pizza_id, label)
);
-- UNIQUE above treats NULL pizza_ids as different, so build-your-own labels need their own index
CREATE UNIQUE INDEX IF NOT EXISTS favourites_byo_label ON favourites (user_id, label) WHERE pizza_id IS NULL;

-- a build-your-own pizza sent from the app for the owner to consider for the menu (migration 007)
CREATE TABLE IF NOT EXISTS suggestions (
  id            INTEGER PRIMARY KEY,
  user_id       INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  name          TEXT NOT NULL DEFAULT '',     -- the sender's name for it; may be empty
  sauce_id      INTEGER REFERENCES sauces(id),
  toppings_json TEXT NOT NULL DEFAULT '[]',   -- [{"id", "side": whole|left|right, "extra"}]
  status        TEXT NOT NULL DEFAULT 'new' CHECK (status IN ('new', 'added', 'dismissed')),
  pizza_id      INTEGER REFERENCES pizzas(id),  -- the menu pizza it became (status 'added')
  created_at    TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at    TEXT NOT NULL DEFAULT (datetime('now'))
);

CREATE TABLE IF NOT EXISTS orders (
  id         INTEGER PRIMARY KEY,
  user_id    INTEGER NOT NULL REFERENCES users(id),
  status     TEXT NOT NULL DEFAULT 'new',   -- new -> preparing -> ready -> collected
  note       TEXT NOT NULL DEFAULT '',
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at TEXT NOT NULL DEFAULT (datetime('now'))
);

-- one row per pizza in an order, with the chosen customisations (rebuilt by migration 004)
CREATE TABLE IF NOT EXISTS order_items (
  id            INTEGER PRIMARY KEY,
  order_id      INTEGER NOT NULL REFERENCES orders(id) ON DELETE CASCADE,
  pizza_id      INTEGER REFERENCES pizzas(id),  -- NULL = build your own
  sauce_id      INTEGER REFERENCES sauces(id),  -- NULL only on orders from before sauces existed
  added_json    TEXT NOT NULL DEFAULT '[]',     -- menu pizza: extra topping ids
  removed_json  TEXT NOT NULL DEFAULT '[]',     -- menu pizza: base topping ids removed
  toppings_json TEXT NOT NULL DEFAULT '[]'      -- [{"id", "side": whole|left|right, "extra"}]: build your own,
                                                -- or a menu pizza whose halves changed (added/removed then
                                                -- approximate it for older clients)
);

-- APNs device tokens for push (separate from the identity UUID above).
-- environment added by migrate_003_devices_environment.py: Xcode builds = sandbox, TestFlight = production.
CREATE TABLE IF NOT EXISTS devices (
  id          INTEGER PRIMARY KEY,
  user_id     INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  token       TEXT NOT NULL UNIQUE,
  environment TEXT NOT NULL DEFAULT 'production' CHECK (environment IN ('production', 'sandbox'))
);
